//! Host-side pixel oracle for application UI integration tests (same font and drawing code).
use nt61_desktop::{applications::{AppId,ApplicationSession,Environment,view},graphics::{Surface,Rect,font::FontLib}};
fn main(){let args:Vec<_>=std::env::args().collect();assert!(args.len()>=4,"application-preview <id> <keys> <output.ppm>");if matches!(args[1].as_str(),"--text"|"--label"|"--status"|"--status-note") {let label=args[1]=="--label";let status=args[1]!="--text"; let mut frame=Surface::new(640,460);frame.fill_rect(0,0,640,460,if status {if args[1]=="--status-note"{0xFFFFF3A6}else{0xFFF3F5F7}}else{0xFF0C0C0C});let font=FontLib::ui().unwrap();font.draw_text(&mut frame,&args[2],10,10,nt61_desktop::shell::layout::UI_FONT_SIZE,if label {0xFF182534}else if status {0xFF526578}else{0xFFF4F4F4}).unwrap();let mut bytes=b"P6\n640 460\n255\n".to_vec();for pixel in frame.pixels(){bytes.extend([(pixel>>16)as u8,(pixel>>8)as u8,*pixel as u8]);}std::fs::write(&args[3],bytes).unwrap();return;}let id=AppId::from_raw(args[1].parse().unwrap()).unwrap();let mut app=ApplicationSession::new(1,id,7919);for key in args[2].bytes(){app.key(key);}let env=Environment{width:1024,height:768,network_adapters:0,audio:false,processes:None,tasks:vec![]};let mut frame=Surface::new(640,460);let font=FontLib::ui().unwrap();let size=nt61_desktop::shell::layout::UI_FONT_SIZE;view::draw(&app,&mut frame,Rect::new(0,0,640,460),&env,|frame,text,b,color|{let mut short=String::new();for c in text.chars(){short.push(c);if font.measure(&short,size).is_some_and(|m|m.width>b.width){short.pop();break;}}let _=font.draw_text(frame,&short,b.x,b.y,size,color);});let mut bytes=format!("P6\n{} {}\n255\n",frame.width(),frame.height()).into_bytes();for pixel in frame.pixels(){bytes.extend([(pixel>>16)as u8,(pixel>>8)as u8,*pixel as u8]);}std::fs::write(&args[3],bytes).unwrap();}
